#pragma once

#include <cstdint>
#include <atomic>
#include <string>
#include <memory>
#include <vector>
#include <utility>
#include <map>

#include <arrow/status.h>
#include <folly/futures/Future.h>

#include "milvus-storage/filesystem/fs.h"
#include "milvus-storage/manifest.h"

#include "milvus-storage/async.h"

namespace milvus_storage::api::transaction {

/**
 * @brief Version constant for fetching the latest manifest
 *
 * When used as a version parameter, LATEST means to fetch the greatest version number.
 * If no manifests exist, the system will generate version 1.
 */
static constexpr int64_t LATEST = -1;

/**
 * @brief Transaction updates tracking class
 *
 * Records all changes made during a transaction that can be used by the resolver
 * Implementation is in transaction.cpp
 */
class Updates {
  public:
  Updates();
  ~Updates();

  [[nodiscard]] bool hasChanges() const;
  void AddColumnGroup(const std::shared_ptr<ColumnGroup>& cg);
  void AppendFiles(const std::vector<std::shared_ptr<ColumnGroup>>& cgs);
  void AddDeltaLog(const DeltaLog& delta_log);
  void UpdateStat(const std::string& key, const Statistics& stat);
  void AddIndex(const Index& index);
  void DropColumn(const std::string& column_name);
  void DropIndex(int64_t index_id);
  void AddLobFile(const LobFileInfo& lob_file);
  [[nodiscard]] const std::vector<std::shared_ptr<ColumnGroup>>& GetAddedColumnGroups() const;
  [[nodiscard]] const std::vector<std::vector<std::shared_ptr<ColumnGroup>>>& GetAppendedFiles() const;
  [[nodiscard]] const std::vector<DeltaLog>& GetAddedDeltaLogs() const;
  [[nodiscard]] const std::map<std::string, Statistics>& GetAddedStats() const;
  [[nodiscard]] const std::vector<Index>& GetAddedIndexes() const;
  [[nodiscard]] const std::vector<std::string>& GetDroppedColumns() const;
  [[nodiscard]] const std::vector<int64_t>& GetDroppedIndexes() const;
  [[nodiscard]] const std::vector<LobFileInfo>& GetAddedLobFiles() const;

  private:
  // Column changes
  std::vector<std::string> dropped_columns_;  // Column names to drop

  // Column group changes
  ColumnGroups added_column_groups_;          // New column groups to add
  std::vector<ColumnGroups> appended_files_;  // Column groups with files to append

  // Delta log changes
  std::vector<DeltaLog> added_delta_logs_;  // New delta logs to add

  // Stats changes
  std::map<std::string, Statistics> added_stats_;  // New stats to add (key -> Statistics)

  // Index changes
  std::vector<Index> added_indexes_;      // Indexes to add or replace
  std::vector<int64_t> dropped_indexes_;  // index_id to drop

  // LOB file changes
  std::vector<LobFileInfo> added_lob_files_;  // New LOB files to add
};

/**
 * @brief Resolver interface for conflict resolution between read and latest manifests.
 *
 * A Resolver implementation reconciles the manifest read when a transaction began
 * with the most recent committed manifest, producing the manifest that will be
 * written by the commit.
 *
 * Resolver instances are expected to be stateless and shared (typically static
 * globals). The caller must keep the Resolver alive for the lifetime of any
 * Transaction that references it.
 */
class Resolver {
  public:
  virtual ~Resolver() = default;

  /**
   * @brief Resolve a commit.
   *
   * @param read_manifest The manifest read when the transaction began
   * @param read_version The version of the read manifest
   * @param latest_manifest The most recent committed manifest at conflict-resolution time
   *        (may be null if the implementation reported requireLatest() == false and the
   *        commit detected version drift; never null when read_version == latest_version
   *        or when requireLatest() == true)
   * @param latest_version The version of the latest manifest
   * @param updates The recorded changes in this transaction
   * @return Resolved manifest or error status
   */
  [[nodiscard]] virtual arrow::Result<std::shared_ptr<Manifest>> resolve(
      const std::shared_ptr<Manifest>& read_manifest,
      int64_t read_version,
      const std::shared_ptr<Manifest>& latest_manifest,
      int64_t latest_version,
      const Updates& updates) const = 0;

  /**
   * @brief Whether this resolver needs the latest manifest contents loaded.
   *
   * When false, the transaction commit logic will skip reading manifest-N.avro
   * from storage on version drift and pass a null latest_manifest to resolve().
   * Implementations that ignore latest_manifest (or only use it when versions
   * match, in which case the read is unnecessary) should return false to avoid
   * spurious commit failures from transient read errors on an otherwise-unused
   * manifest file.
   */
  [[nodiscard]] virtual bool requireLatest() const = 0;
};

// ==================== Helper Functions ====================

/**
 * @brief Apply updates to a manifest
 *
 * Creates a copy of the manifest and applies all updates (appended files, added column groups,
 * delta logs, stats) to it.
 *
 * @param manifest Base manifest to apply updates to
 * @param updates Updates to apply
 * @return New manifest with updates applied, or error status
 */
arrow::Result<std::shared_ptr<Manifest>> applyUpdates(const std::shared_ptr<Manifest>& manifest,
                                                      const Updates& updates);

// ==================== Helper Resolver Functions ====================

/**
 * @brief Resolver that applies updates to read_manifest, overwriting any concurrent changes
 *
 * This resolver applies all changes (appended files, added column groups, delta logs, stats)
 * into the read_manifest, ignoring any concurrent changes in latest_manifest.
 * requireLatest() == false — the commit logic skips reading manifest-N.avro on version drift.
 */
extern const Resolver& OverwriteResolver;

/**
 * @brief Resolver that fails if latest version differs from read version
 *
 * When read_version equals latest_version, applies updates to latest_manifest (or
 * read_manifest if latest_manifest is null). When versions differ, returns a
 * TxnResolutionFailed error without touching latest_manifest.
 *
 * requireLatest() == false: it is safe for Commit() to skip reading manifest-N.avro on
 * version drift, since the resolver only inspects manifests when versions match.
 */
extern const Resolver& FailResolver;

class Transaction;

struct OpenResult {
  AsyncStatus status;
  std::unique_ptr<Transaction> transaction;
};

enum class CommitOutcome { NotCommitted, Committed, Unknown };
struct CommitResult {
  AsyncStatus status;
  CommitOutcome outcome = CommitOutcome::NotCommitted;
  int64_t version = -1;
  int64_t manifest_size = -1;  ///< Written manifest size in bytes; -1 unless committed
};

class Transaction {
  public:
  // Static factory method to open a transaction
  // @param fs Filesystem to use
  // @param base_path Base path for the storage
  // @param version Version to read from (default: LATEST = fetch greatest version)
  // @param manifest_size Exact size of the manifest at version, or <= 0 if unknown.
  //        Ignored for LATEST, whose version is not known until listing completes.
  // @param resolver Resolver for conflict resolution (default: FailResolver). The
  //        Transaction stores a non-owning pointer to this object; the caller MUST keep
  //        the resolver alive for the lifetime of the returned Transaction. Do not pass
  //        a temporary.
  // @param retry_limit Maximum number of retry attempts on commit conflicts (default: 1)
  static arrow::Result<std::unique_ptr<Transaction>> Open(const milvus_storage::ArrowFileSystemPtr& fs,
                                                          const std::string& base_path,
                                                          int64_t version = LATEST,
                                                          int64_t manifest_size = -1,
                                                          const Resolver& resolver = FailResolver,
                                                          uint32_t retry_limit = 1);

  // Lazy scheduling of the existing synchronous transaction API. Consume on a
  // caller-owned blocking-work executor. No filesystem or transport is replaced.
  // Cancellation/deadline checks happen before Open starts; in-flight synchronous
  // I/O cannot be interrupted. The executor must accept tasks through completion.
  // Keep the resolver alive for the lifetime of the returned transaction. Dropping
  // an unconsumed future starts no work; releasing its handle does not cancel it.
  static folly::SemiFuture<OpenResult> OpenAsync(const std::string& path,
                                                 Properties properties,
                                                 int64_t version,
                                                 int64_t manifest_size,
                                                 const Resolver& resolver,
                                                 uint32_t retries,
                                                 uint64_t timeout_ms,
                                                 std::shared_ptr<AsyncOperation>& operation,
                                                 ArrowFileSystemPtr filesystem = nullptr);

  ~Transaction() = default;

  // Commit using Updates (uses the resolver set via Open)
  // Returns the committed version number on success; optionally outputs the written
  // manifest size in bytes. The output is unchanged on failure.
  arrow::Result<int64_t> Commit(int64_t* out_manifest_size = nullptr);

  // Schedules Transaction::Commit on the consuming executor. A discarded lazy
  // future releases its reservation; execution consumes the transaction even on
  // cancellation/failure. Keep it alive and unmodified until completion. Errors
  // from the synchronous commit conservatively carry Unknown; only pre-execution
  // rejection/cancellation/deadline can guarantee NotCommitted. In-flight calls
  // run to completion and success wins over cancellation or deadline expiry.
  folly::SemiFuture<CommitResult> CommitAsync(uint64_t timeout_ms, std::shared_ptr<AsyncOperation>& operation);

  // Get manifest on read version
  // Returns empty manifest if read_version_ is 0 (no manifest exists)
  arrow::Result<std::shared_ptr<Manifest>> GetManifest();

  // Get the read version of this transaction
  [[nodiscard]] int64_t GetReadVersion() const;

  // ==================== Fluent-style Builder Methods ====================

  /**
   * @brief Drop a single column from the manifest
   *
   * Removes the column from its column group. If the column group becomes
   * empty after removal, the entire column group is removed.
   * Automatically drops all indexes on this column.
   * Noop if the column doesn't exist (consistent with DropIndex).
   *
   * @param column_name Name of the column to drop
   * @return Reference to this transaction for method chaining
   */
  Transaction& DropColumn(const std::string& column_name);

  /**
   * @brief Add a new column group to the transaction updates
   * @param cg Column group to add
   * @return Reference to this transaction for method chaining
   */
  Transaction& AddColumnGroup(const std::shared_ptr<ColumnGroup>& cg);

  /**
   * @brief Append files to existing column groups
   * @param cgs Column groups containing files to append
   * @return Reference to this transaction for method chaining
   */
  Transaction& AppendFiles(const std::vector<std::shared_ptr<ColumnGroup>>& cgs);

  /**
   * @brief Add a delta log to the transaction updates
   * @param delta_log Delta log to add
   * @return Reference to this transaction for method chaining
   */
  Transaction& AddDeltaLog(const DeltaLog& delta_log);

  /**
   * @brief Add a stat entry to the transaction updates
   * @param key Stat key (e.g., "pk.delete", "bloomfilter", "bm25")
   * @param stat Statistics containing file paths and optional metadata
   * @return Reference to this transaction for method chaining
   */
  Transaction& UpdateStat(const std::string& key, const Statistics& stat);

  /**
   * @brief Record or replace metadata for an already-written index file.
   *
   * This method only records Index metadata. It does not perform index-file
   * I/O or return a file handle. Relative paths are resolved under _index/;
   * commit rejects newly added/replaced paths that normalize to a leading parent component.
   */
  Transaction& AddIndexInfo(const Index& index);

  /**
   * @brief Drop all completed artifacts for an index.
   * @return Reference to this transaction for method chaining
   */
  Transaction& DropIndex(int64_t index_id);

  /**
   * @brief Add a LOB file to the transaction updates
   * @param lob_file LOB file info to add
   * @return Reference to this transaction for method chaining
   */
  Transaction& AddLobFile(const LobFileInfo& lob_file);

  private:
  friend struct AsyncManifestOperation;
  std::atomic<bool> async_consumed_{false};
  // Private constructor - use Open() factory method instead
  Transaction(const milvus_storage::ArrowFileSystemPtr& fs,
              const std::string& base_path,
              int64_t read_version,
              const Resolver& resolver,
              uint32_t retry_limit);

  // Get latest version from filesystem
  arrow::Result<int64_t> get_latest_version();

  // Read manifest from filesystem at given version
  arrow::Result<std::shared_ptr<Manifest>> read_manifest(int64_t version, int64_t manifest_size = -1);

  arrow::Status write_manifest(const std::shared_ptr<Manifest>& manifest,
                               int64_t old_version,
                               int64_t new_version,
                               int64_t* out_manifest_size);

  int64_t read_version_;
